<?php

declare(strict_types=1);

namespace App\Services\Contract;

final class ContractStandardTemplateText
{
    public static function sections(string $code): array
    {
        $consumer = $code === 'household-repair';
        $supply = $code === 'supply';
        $first = $supply ? 'Покупатель' : ($code === 'subcontract' ? 'Генеральный подрядчик' : 'Заказчик');
        $second = $supply ? 'Поставщик' : ($code === 'subcontract' ? 'Субподрядчик' : 'Подрядчик');
        $sections = [self::section('parties', 'Стороны и предмет договора', [
            $first.' {payer}'.($code === 'subcontract' ? ' (далее — Заказчик)' : '').' и '.$second.' {executor}'.($code === 'subcontract' ? ' (далее — Подрядчик)' : '').', далее совместно — Стороны, заключили настоящий договор. Представители действуют на основании документов, указанных в реквизитах; каждый представитель подтверждает наличие полномочий на подписание. При личном участии физического лица оно подписывает договор самостоятельно.',
            $supply ? 'Поставщик обязуется передать Покупателю товары, а Покупатель — принять и оплатить их. Наименование и согласованный состав поставки: {subject}. Номенклатура, количество, единицы измерения, характеристики и цены определены в приложении № 1.'
                : 'Подрядчик обязуется выполнить согласованные работы, передать их результат Заказчику, а Заказчик — принять и оплатить результат. Предмет, состав и результат работ: {subject}. Объём и единичные цены конкретизированы в приложении № 1; этапы и сроки — в приложении № 2.',
            'Место выполнения работ / передачи результата или товара: {location}. Указание проекта в заголовке не заменяет описание предмета и места исполнения. Приложения № 1 и № 2 составляют часть договора и согласуются Сторонами вместе с ним.',
        ])];
        if ($code === 'subcontract') {
